		setPosition(OverlayPosition.TOP_LEFT);
	}

	public void addEntry(int listIndex, String text, Color color, Color bgColor, int fontSize, OverlayDisplayMode mode, int durationSeconds, int offsetX, int offsetY)
	{
		entries.removeIf(e -> e.listIndex == listIndex);

		Instant expireTime;
		if (mode == OverlayDisplayMode.SOLID_UNTIL_CANCELLED)
		{
			expireTime = Instant.MAX;
		}
		else
		{
			expireTime = Instant.now().plusSeconds(durationSeconds);
		}

		boolean flash = (mode == OverlayDisplayMode.FLASH_TIMED);
		boolean untilCancelled = (mode == OverlayDisplayMode.SOLID_UNTIL_CANCELLED);
		Font font = new Font(Font.SANS_SERIF, Font.BOLD, fontSize);
		entries.add(new OverlayEntry(listIndex, text, color, bgColor, font, expireTime, flash, untilCancelled, offsetX, offsetY));
	}

	public void cancelEntry(int listIndex)
	{
		entries.removeIf(e -> e.listIndex == listIndex);
	}

	public void cancelUntilCancelledEntries()
	{
		entries.removeIf(e -> e.untilCancelled);
	}

	public void clearEntries()
	{
		entries.clear();
	}

	public boolean hasEntries()
	{
		return !entries.isEmpty();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (entries.isEmpty())
		{
			return null;
		}

		Instant now = Instant.now();
		long currentMs = System.currentTimeMillis();
		entries.removeIf(e -> now.isAfter(e.expireTime));

		int maxX = 0;
		int maxY = 0;
		boolean anyRendered = false;

		for (OverlayEntry entry : entries)
		{
			// For flashing entries, skip rendering every other 500ms cycle
			if (entry.flash && (currentMs / 500) % 2 == 0)
			{
				continue;
			}

			graphics.setFont(entry.font);
			FontMetrics fm = graphics.getFontMetrics();

			int textWidth = fm.stringWidth(entry.text);
			int textHeight = fm.getHeight();
			int padding = 4;

			// Draw background
			graphics.setColor(entry.bgColor);
			graphics.fillRect(entry.offsetX - padding, entry.offsetY, textWidth + padding * 2, textHeight + 2);

			// Draw text
			graphics.setColor(entry.color);
			graphics.drawString(entry.text, entry.offsetX, entry.offsetY + fm.getAscent());

			maxX = Math.max(maxX, entry.offsetX + textWidth + padding * 2);
			maxY = Math.max(maxY, entry.offsetY + textHeight + 2);
			anyRendered = true;
		}

		if (!anyRendered)
		{
			return null;
		}

		return new Dimension(maxX, maxY);
	}

	private static class OverlayEntry
	{
		final int listIndex;
		final String text;
		final Color color;
		final Color bgColor;
		final Font font;
		final Instant expireTime;
		final boolean flash;
		final boolean untilCancelled;
		final Instant addedAt;
		final int offsetX;
		final int offsetY;

		OverlayEntry(int listIndex, String text, Color color, Color bgColor, Font font, Instant expireTime, boolean flash, boolean untilCancelled, int offsetX, int offsetY)
		{
			this.listIndex = listIndex;
			this.text = text;
			this.color = color;
			this.bgColor = bgColor;
			this.font = font;
			this.expireTime = expireTime;
			this.flash = flash;
			this.untilCancelled = untilCancelled;
			this.addedAt = Instant.now();
			this.offsetX = offsetX;
			this.offsetY = offsetY;
		}
	}
}

package com.enhancedchatnotifications;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.base.MoreObjects;
import com.google.common.base.Splitter;
import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Notification;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
		name = "Enhanced Chat Notifications",
		description = "Enable multiple custom notifications based on chat messages",
		tags = {"chat", "notifications"}
)
public class EnhancedChatNotificationsPlugin extends Plugin
{
	static final int MAX_LISTS = 25;
	private static final String CONFIG_GROUP = "enhancedchatnotifications";

	@Inject
	private Client client;

	@Inject
	private EnhancedChatNotificationsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private EnhancedChatNotificationsOverlay overlay;

	@Inject
	@Named("runelite.title")
	private String runeliteTitle;

	private final List<List<Pattern>> allListPatterns = new ArrayList<>();

	private final MouseListener mouseListener = new MouseListener()
	{
		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			overlay.cancelUntilCancelledEntries();
			return e;
		}

		@Override
		public MouseEvent mousePressed(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseReleased(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseEntered(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseExited(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseDragged(MouseEvent e) { return e; }
		@Override
		public MouseEvent mouseMoved(MouseEvent e) { return e; }
	};

	private final KeyListener keyListener = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent e)
		{
			overlay.cancelUntilCancelledEntries();
		}

		@Override
		public void keyReleased(KeyEvent e) {}
		@Override
		public void keyTyped(KeyEvent e) {}
	};

	@Provides
	EnhancedChatNotificationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EnhancedChatNotificationsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseListener);
		keyManager.registerKeyListener(keyListener);
		updateNotifications();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(mouseListener);
		keyManager.unregisterKeyListener(keyListener);
		overlay.clearEntries();
		allListPatterns.clear();
	}
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(CONFIG_GROUP))
		{
			updateNotifications();
		}
	}

	private void updateNotifications()
	{
		allListPatterns.clear();

		int listCount = MAX_LISTS;

		for (int i = 1; i <= listCount; i++)
		{
			List<Pattern> patterns = new ArrayList<>();

			Notification notification = getNotificationEnabled(i);
			if (!notification.isEnabled())
			{
				allListPatterns.add(patterns);
				continue;
			}

			String words = getNotificationWords(i);
			if (words != null && !words.trim().isEmpty())
			{
				List<String> items = Text.fromCSV(words);
				String joined = items.stream()
						.map(Text::escapeJagex)
						.map(this::quoteAndIgnoreColor)
						.collect(Collectors.joining("|"));
				Pattern p = compilePattern("(?:\\b|(?<=\\s)|\\A)(?:" + joined + ")(?:\\b|(?=\\s)|\\z)");
				if (p != null)
				{
					patterns.add(p);
				}
			}

			String regex = getNotificationRegex(i);
			if (regex != null && !regex.trim().isEmpty())
			{
				Splitter.on("\n")
						.omitEmptyStrings()
						.trimResults()
						.splitToList(regex).stream()
						.map(EnhancedChatNotificationsPlugin::compilePattern)
						.filter(Objects::nonNull)
						.forEach(patterns::add);
			}

			allListPatterns.add(patterns);
		}
	}

	private String getNotificationWords(int list)
	{
		String val = configManager.getConfiguration(CONFIG_GROUP, "notificationWords" + list);
		return val != null ? val : "";
	}

	private String getNotificationRegex(int list)
	{
		String val = configManager.getConfiguration(CONFIG_GROUP, "notificationRegex" + list);
		return val != null ? val : "";
	}

	private Notification getNotificationEnabled(int list)
	{
		Notification n = configManager.getConfiguration(CONFIG_GROUP, "notificationEnabled" + list, Notification.class);
		return n != null ? n : Notification.OFF;
	}

	private String getOverlayText(int list)
	{
		String val = configManager.getConfiguration(CONFIG_GROUP, "overlayText" + list);
		return val != null ? val : "";
	}

	private Color getOverlayColor(int list)
	{
		Color c = configManager.getConfiguration(CONFIG_GROUP, "overlayColor" + list, Color.class);
		return c != null ? c : Color.WHITE;
	}

	private int getOverlaySize(int list)
	{
		Integer s = configManager.getConfiguration(CONFIG_GROUP, "overlaySize" + list, Integer.class);
		return s != null ? s : 16;
	}

	private int getOverlayX(int list)
	{
		Integer x = configManager.getConfiguration(CONFIG_GROUP, "overlayX" + list, Integer.class);
		return x != null ? x : 0;
	}

	private int getOverlayY(int list)
	{
		Integer y = configManager.getConfiguration(CONFIG_GROUP, "overlayY" + list, Integer.class);
		return y != null ? y : 0;
	}

	private Color getOverlayBgColor(int list)
	{
		Color c = configManager.getConfiguration(CONFIG_GROUP, "overlayBgColor" + list, Color.class);
		return c != null ? c : Color.BLACK;
	}

	private static Pattern compilePattern(String pattern)
	{
		try
		{
			return Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
		}
		catch (PatternSyntaxException ex)
		{
			return null;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		MessageNode messageNode = chatMessage.getMessageNode();
		boolean update = false;

		switch (chatMessage.getType())
		{
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case DIALOG:
			case MESBOX:
				return;
			case MODCHAT:
			case PUBLICCHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				if (client.getLocalPlayer() != null && Text.toJagexName(Text.removeTags(chatMessage.getName())).equals(client.getLocalPlayer().getName()))
				{
					return;
				}
				break;
			case CONSOLE:
				if (chatMessage.getName().equals(runeliteTitle))
				{
					return;
				}
				break;
		}

		String nodeValue = messageNode.getValue();

		for (int listIdx = 0; listIdx < allListPatterns.size(); listIdx++)
		{
			List<Pattern> patterns = allListPatterns.get(listIdx);
			boolean matchesThisList = false;

			for (Pattern pattern : patterns)
			{
				Matcher matcher = pattern.matcher(nodeValue);
				if (!matcher.find())
				{
					continue;
				}

				StringBuffer stringBuffer = new StringBuffer();

				do
				{
					final int end = matcher.end();
					final String closeColor = MoreObjects.firstNonNull(
							getLastColor(nodeValue.substring(0, end)),
							"<col" + ChatColorType.NORMAL + '>');
					final String value = stripColor(matcher.group());

					matcher.appendReplacement(stringBuffer, "<col" + ChatColorType.HIGHLIGHT + '>' + value + closeColor);

					update = true;
					matchesThisList = true;
				}
				while (matcher.find());

				matcher.appendTail(stringBuffer);
				nodeValue = stringBuffer.toString();
			}

			if (matchesThisList)
			{
				int listNum = listIdx + 1;
				Notification notification = getNotificationEnabled(listNum);
				if (notification.isEnabled())
				{
					sendNotification(notification, chatMessage);

					String overlayText = getOverlayText(listNum);
					if (!overlayText.isEmpty())
					{
						overlay.addEntry(listNum, overlayText, getOverlayColor(listNum), getOverlayBgColor(listNum), getOverlaySize(listNum), config.overlayDisplayMode(), config.overlayDuration(), getOverlayX(listNum), getOverlayY(listNum));
					}
				}
			}
		}

		if (update)
		{
			messageNode.setValue(nodeValue);
			messageNode.setRuneLiteFormatMessage(messageNode.getValue());
		}
	}

	private void sendNotification(Notification notification, ChatMessage message)
	{
		String name = Text.removeTags(message.getName());
		String sender = message.getSender();
		StringBuilder stringBuilder = new StringBuilder();

		if (!Strings.isNullOrEmpty(sender))
		{
			stringBuilder.append('[').append(sender).append("] ");
		}

		if (!Strings.isNullOrEmpty(name))
		{
			stringBuilder.append(name).append(": ");
		}

		stringBuilder.append(Text.removeTags(message.getMessage()));
		notifier.notify(notification, stringBuilder.toString());
	}

	private String quoteAndIgnoreColor(String str)
	{
		StringBuilder stringBuilder = new StringBuilder();

		for (int i = 0; i < str.length(); ++i)
		{
			char c = str.charAt(i);
			stringBuilder.append(Pattern.quote(String.valueOf(c)));
			stringBuilder.append("(?:</?col[^>]*>)*");
		}

		return stringBuilder.toString();
	}

	private static String getLastColor(String str)
	{
		int colIdx = str.lastIndexOf("<col=");
		int colEndIdx = str.lastIndexOf("</col>");

		if (colEndIdx > colIdx)
		{
			return "<col" + ChatColorType.NORMAL + ">";
		}

		if (colIdx == -1)
		{
			return null;
		}

		int closeIdx = str.indexOf('>', colIdx);
		if (closeIdx == -1)
		{
			return null;
		}

		return str.substring(colIdx, closeIdx + 1);
	}

	@VisibleForTesting
	static String stripColor(String str)
	{
		return str.replaceAll("(<col=[0-9a-f]+>|</col>)", "");
	}
}

package com.enhancedchatnotifications;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum OverlayDisplayMode
{
	SOLID_TIMED("Solid for X seconds"),
	FLASH_TIMED("Flash for X seconds"),
	SOLID_UNTIL_CANCELLED("Solid until cancelled");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

